"""Publish a focused before/after report for the three user-confirmed defects."""
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
before=json.loads((ROOT/'data/reson-first20/before-speaker-fix.json').read_text(encoding='utf-8'))
after=json.loads((ROOT/'data/reson-speaker-fix/results.json').read_text(encoding='utf-8'))
esc=html.escape
explanations={1:'Короткие фрагменты, отмеченные вторым голосом, блокировали всю запись. Теперь явное преобладание основного голоса позволяет сохранить его реплику.',
6:'Начальная фоновая фраза «по размеру ледовых площадок» была объединена с клиентом. Отдельный тихий участок до основной речи теперь отсекается по относительному уровню и сходству голоса.',
9:'Несколько меток второго голоса и небольшая ошибка границ приводили к отказу. Теперь короткое пересечение границ не блокирует явно преобладающую речь.'}
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Фокус · Голос · исправления 1, 6, 9</title><style>body{margin:0;background:#f3f5fa;color:#172337;font:16px/1.65 system-ui}.wrap{max-width:1060px;margin:40px auto;padding:0 22px}h1{font-size:36px;line-height:1.2}h2{font-size:22px}h3{font-size:14px;color:#64748b;margin-bottom:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px}.stat,article,section{background:white;border:1px solid #dde4f0;border-radius:18px;padding:24px;margin-bottom:20px}.stat strong{font-size:28px;display:block}.pass{color:#12784c}.reason{padding:14px;background:#eef3ff;border-radius:12px}.muted{color:#65758c;font-size:14px}.pair{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px}.old{border-left:3px solid #d7a0a0;padding-left:14px}.new{border-left:3px solid #61ae8c;padding-left:14px}table{width:100%;border-collapse:collapse}td,th{padding:10px;text-align:left;border-bottom:1px solid #e0e7f0}pre{white-space:pre-wrap;background:#f5f7fb;padding:16px;border-radius:12px}a{color:#294dad}</style><div class="wrap"><p class="muted">ФОКУС · ФИЛЬТР ГОЛОСА · 15 ОКТЯБРЯ 2026</p><h1>Исправлены записи №1, №6 и №9</h1><p>Повторно обработаны те же первые 20 записей general_noisily. Распознавание использует аудио; эталонные тексты применяются только после обработки для сравнения.</p>'''
def pct(v):return f'{v*100:.2f}%'
b,a=before['metrics']['spoken'],after['metrics']['spoken']
page+=f'<div class="grid"><div class="stat">WER по всем 20 записям<strong>{pct(b["wer"])} → <span class="pass">{pct(a["wer"])}</span></strong></div><div class="stat">Отказы фильтра<strong>{before["repeat_requests"]} → <span class="pass">{after["repeat_requests"]}</span></strong></div><div class="stat">Фокус пользователя<strong class="pass">3 из 3 совпали</strong></div></div>'
for number in (1,6,9):
    old=before['rows'][number-1];new=after['rows'][number-1]
    assert old['audio_sha256']==new['audio_sha256']
    page+=f'<article id="case-{number}"><h2>№{number} · <span class="pass">совпало с эталоном</span></h2><p class="reason">{esc(explanations[number])}</p><p class="muted">{esc(new["id"])} · одна и та же запись, SHA-256 совпадает</p><h3>Эталон сайта</h3><p>{esc(new["text"])}</p><div class="pair"><div class="old"><h3>До · WER {pct(old["spoken"]["wer"])}</h3><p>{esc(old["hypothesis"] or "Вся реплика отклонена; агент не получил текст")}</p></div><div class="new"><h3>После · WER {pct(new["spoken"]["wer"])}</h3><p>{esc(new["hypothesis"])}</p></div></div><details><summary>Диагностика фильтра</summary><pre>{esc(json.dumps(new.get("speaker",{}),ensure_ascii=False,indent=2))}</pre></details></article>'
page+='<section><h2>Что изменилось в движке</h2><p>В первой реплике выбирается явно преобладающий говорящий. VAD восстанавливает границы слов, которые сегментация говорящих определила слишком узко. Тихие отдельные вводные и завершающие фразы другого голоса отсекаются; тихие слова внутри основного ответа сохраняются. Короткие расхождения границ допускаются, значительное наложение голосов по-прежнему требует повторения.</p><p>Образец нового голоса сохраняется только после успешной проверки реплики. Проверены тихое начало того же клиента, тихая речь внутри ответа, неоднозначные голоса и повтор №6 после запоминания голоса.</p><p class="muted">Выбор основного голоса без заранее записанного образца остаётся эвристикой. Проверка на этих 20 файлах не гарантирует результат при любом расположении микрофона и голосов. Модели T-one/GigaAM и их веса не менялись.</p></section>'
page+=f'<section><h2>Все 20 записей — контроль результата</h2><p>Точных совпадений слов: {b["exact_recordings"]}/20 → {a["exact_recordings"]}/20. Ошибок слов: {b["word_errors"]}/{b["reference_words"]} → {a["word_errors"]}/{a["reference_words"]}. Пунктуация, регистр, ё/е и отдельные междометия нормализованы одинаково. Технических ошибок: {after["technical_errors"]}.</p><details><summary>Остальные записи — без отдельных исправлений написания</summary><table><tr><th>№</th><th>WER до</th><th>WER после</th></tr>'
for old,new in zip(before['rows'],after['rows']):
    page+=f'<tr><td>{new["number"]}</td><td>{pct(old["spoken"]["wer"])}</td><td>{pct(new["spoken"]["wer"])}</td></tr>'
page+='</table></details><p>Это последовательная выборка из 20 шумных телефонных записей. Изменение WER отражает исправления фильтра на этих файлах.</p><p><a href="/static/qa/reson-first20.html">Открыть исходный отчёт до исправления</a> · <a href="https://huggingface.co/datasets/MTSAIR/mws-reson-asr-osd">Датасет MTSAIR</a></p><p class="muted">Данные: MIT, © 2026 MTS AI. Ревизия 21301635963415883d3868fd88b26d1df19881e9.</p></section></div></html>'
(ROOT/'static/qa/reson-speaker-fix.html').write_text(page,encoding='utf-8')
print('http://127.0.0.1:8000/static/qa/reson-speaker-fix.html')
